head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > getDataType]<br/>Body Column 정보를 사용하여 특정 Body Column 의 dataType 속성값을 반환합니다.",
    "validation" : [
        "columnInfo(필수) 파라미터로 dataType 속성값을 조회할 Body Column 의 ID 를 설정할 수 있어야 합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target / dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    $c.gcm.createLabel('label="[전제] col1=number, col3=date 로 Body Column dataType 설정. col2 는 숨김 처리. col4 는 Body Column dataType 미설정 + 바인딩 DataList col4 dataType=text 설정\n[절차] columnInfo(Body Column ID) 선택 후 getDataType 실행\n[확인] 반환 dataType 이 col1=number / col2=float / col3=date / col4=text(DataList 폴백) 인지 확인"', '', 'label1');

    // dataList 생성 + 바인딩
    $c.gcm.createBasicDataList('', '', 'dlt_bind');

    // 검증용 초기 데이터 설정
    //  (바인딩 DataList 의 col4 Column 은 createBasicDataList 기본 dataType='text' -> Body Column dataType 미설정 시 폴백 검증용)
    dlt_bind.setJSON([
        { "col1": "12345", "col2": "67890", "col3": "20251225", "col4": "abc" }
    ]);

    let properties = { dataList: "data:dlt_bind" };
    let cList = $c.gcm.createCList(properties);

    // target 생성 (기본 4컬럼 col1~col4)
    await $c.gcm.createBasicGridView(cList);

    // Body Column dataType 설정 : col1=number, col2=float, col3=date
    //  (col4 는 미설정 -> 바인딩 DataList col4 의 dataType='text' 폴백 반환)
    target1.setDataType(0, "number");
    target1.setDataType(1, "float");
    target1.setDataType(2, "date");

    // col2 숨김 처리
    target1.setColumnVisible(1, false);
}



scwin.btn_getDataType_onclick = function () {
    // columnInfo 에 Body Column 의 ID 문자열 전달
    let columnInfo = par_columnInfo.getValue();

    // 파라미터에 해당하는 Body Column 의 dataType 속성값 반환
    let dataType = target1.getDataType(columnInfo);

    wf_body_bottom.getObj("scwin").setReturnValue("getDataType(\"" + columnInfo + "\") : " + dataType);
}
